    'pv_L10_006': 'ධර්මය පුරුදු කරන කෙනෙක් (masc. -ī)',
    'pv_L10_007': 'ධනය, දේපල (නපුරු)',
    'pv_L10_008': 'දුක්ඛිත තත්වය, නරක ගමනාන්තය (fem.)',
    'pv_L10_009': 'ඇත්තෙන්ම, ඇත්තෙන්ම (අතුරුදහන් කළ නොහැකි)',
    'pv_L10_010': 'වැනි, (ඉවත් කළ නොහැකි)',
    'pv_L10_011': 'මව (fem. -ī)',
    'pv_L10_012': 'රැජින, රාජකීය භාර්යාව (fem. -ī)',
    'pv_L10_013': 'ප්‍රඥාවන්ත, බුද්ධිමතෙක් (masc. -ī)',
    'pv_L10_014': 'නපුර, පාපය (නපුංසක)',
    'pv_L10_015': 'නපුර කරන්නා (masc. -ī)',
    'pv_L10_016': 'කුසල්, යහපත් ක්‍රියාව (නපුරු)',
    'pv_L10_017': 'පින් කරන්නා (masc. -ī)',
    'pv_L10_018': 'ප්‍රමුඛ, ප්‍රධාන, හොඳම (විශේෂණ)',
    'pv_L10_019': 'ප්‍රීතිමත් තත්වයක්, හොඳ ගමනාන්තයක් (fem.)',
    'pv_L10_020': 'එළුවා (fem., aja වෙතින්)',
    'pv_L10_021': 'mare (fem., assa වෙතින්)',
    'pv_L10_022': 'කාන්තා ගිහි අනුගාමිකයා (fem., upāsaka වෙතින්)',
    'pv_L10_023': 'සේවිකාව, සේවිකාව (ස්ත්‍රිය, dāsa වෙතින්)',
    'pv_L10_024': 'දේවතාවිය, රැජින (fem., deva වෙතින්)',
    'pv_L10_025': 'රැජින (fem., rāja වෙතින්)',
    'pv_L10_026': 'ගැහැණු අලි (කාන්තා., හත්ති සිට)',
    'pv_L10_027': 'ප්‍රඥාවේ කාන්තාව (fem., medhāvī වෙතින්)',
    'pv_L10_028': 'භික්ෂුණිය (fem., භික්ෂුවගෙන්)',
    'pv_L10_029': 'නැන්දා (මාතෘ) (ස්ත්‍රී., mātula සිට අක්‍රමවත්)',
    'pv_L10_030': 'ගෘහපතියාගේ බිරිඳ (ගැහැණු, ගහපති සිට අක්‍රමවත්)',
    'pv_L10_031': 'සහෝදරිය (එකම දෙමාපිය) (ෆෙම්.)\nඅතේ මල් සහිත',
    'pv_L10_032': 'එකක් (fem.)',
    'pv_L10_033': 'ආරක්ෂා කරයි, ආරක්ෂා කරයි',
    'pv_L10_034': 'කරයි, කරයි; අතීතය: akaṃsu / katvā (කළ පසු)',
    'pv_L10_035': 'දෙයි, ප්‍රදානය කරයි; අතීතය: adaṃsu (ඔවුන් දුන්නා)',
    'pv_L10_036': 'ගියා (ගච්චති අතීතය)',
    'pv_L10_037': 'ළඟා වේ, ළඟා වේ; අනාගතය: pāpuṇissati; අතීතය: pāpuṇi',
    'pv_L10_038': 'සහභාගී වේ, බලා ගනී, සේවය කරයි',
    'pv_L10_039': 'යනු, වෙයි; අතීතය: āsi (pl. homa = අපි / බවට පත් වුණා)',
    'pv_L10_040': 'වැටෙනවා, වැටෙනවා, බහිනවා; අතීතය: පති (වැටුණු)',
    'pv_L10_041': 'දකියි; අතීතය: addasa / disvā (බැලීමෙන් පසු)',
    'pv_L10_042': 'ධාවනය; අතීතය: dhāviṃsu (ඔවුන් දිව්වා)',
    'pv_L10_043': 'පලා යයි, පලා යයි; අතීතය: palāyiṃsu (ඔවුන් පලා ගියා)',
    'pv_L10_044': 'අධ්‍යයන, මාස්ටර්',
    'pv_L10_045': 'ඉහළට නගිනවා, සවිකරයි',
    'pv_L10_046': 'අලි (masc. -i/-ī)',
    'pv_L10_047': 'අලි (සංඛ්‍යා. hatthī / පිරිමි අලියා)',
    'pv_L10_048': 'my (සන්තක සර්වනාමය)',
    'pv_L10_049': 'ඔහුගේ/ඇය (සර්වනාමය)',
    'pv_L10_050': 'දානමය ආහාර, ආහාර (දානයෙන් ලබාගත්) (මස්ක්.)',
    'pv_L10_051': 'ඊයේ (කාල ඇඩ්වර්බ්)',
    'pv_L12_001': 'මම (නාම. sg.)',
    'pv_L12_002': 'අපි (නම්. pl.)',
    'pv_L12_003': 'මම (ac. sg.)',
    'pv_L12_004': 'විසින්/මා හරහා, මා සමඟ (inst./abl. sg.)',
    'pv_L12_005': 'මගේ, මට (gen./dat. sg.)',
    'pv_L12_006': 'මා තුළ, මා මත (loc. sg.)',
    'pv_L12_007': 'මම / මගේ / මා සඳහා (එන්ක්ලිටික්, වාක්‍යයේ ආරම්භයේ දී නොවේ)',
    'pv_L12_008': 'අපි / අපගේ (එන්ක්ලිටික්, වාක්‍යයේ ආරම්භයේදී නොවේ)',
    'pv_L12_009': 'ඔබ (සංඛ්‍යා. sg.)',
    'pv_L12_010': 'ඔබ (pl.) (No./acc. pl.)',
    'pv_L12_011': 'ඔබ (acc. sg.)',
    'pv_L12_012': 'විසින්/ඔබ හරහා (inst./abl. sg.)',
    'pv_L12_013': 'ඔබේ, ඔබ වෙනුවෙන් (gen./dat. sg.)',
    'pv_L12_014': 'ඔබ තුළ, ඔබ මත (loc. sg.)',
    'pv_L12_015': 'ඔබ / ඔබේ / ඔබ වෙනුවෙන් (වැකිය ආරම්භයේදී නොවේ)',
    'pv_L12_016': 'ඔබ (pl.) / ඔබගේ (වැකිය ආරම්භයේදී නොවේ)',
    'pv_L12_017': 'බොරුකාරයා, බොරු කථිකයා (masc.)',
    'pv_L12_018': 'වාර්තා කරයි, දන්වයි, නිවේදනය කරයි',
    'pv_L12_019': 'දුෂ්ට පුද්ගලයා, නරක පුද්ගලයා; දුෂ්ට (masc./විශේෂණ)',
    'pv_L12_020': 'සේවය කරයි, ආශ්‍රය කරයි, සමීප වේ',
    'pv_L12_021': 'පවසයි, සජ්ඣායනා කරයි, දේශනා කරයි (උදා. bhaṇeyya = කිව යුතුය)',
    'pv_L12_022': 'දීම, දානය, පරිත්‍යාගශීලි බව (නපුංසක)',
    'pv_L12_023': 'මෙලෙස, එසේ (ඉවත් කළ නොහැකි)',
    'pv_L12_024': 'ජය ගනී, ජය ගනී',
    'pv_L12_025': 'කාලකණ්ණි, මසුරු පුද්ගලයා (masc.)',
    'pv_L12_026': 'කෝපය, කෝපය (මැස්ක්.)',
    'pv_L12_027': 'ඉක්මනින්, එකවර (ක්‍රියා පදය)',
    'pv_L12_028': 'ප්‍රඥාවන්ත, උගත් පුද්ගලයා (masc.)',
    'pv_L12_029': 'නරක, නපුරු, පව්කාර (විශේෂණ පදය)',
    'pv_L12_030': 'හොඳ පුද්ගලයෙක්; යහපත්, විශිෂ්ඨ; හොඳින් කළා! (masc./adverb/exclamation)',
    'pv_L12_031': 'උත්සාහ කරයි, උත්සාහ කරයි, උත්සාහ කරයි',
    'pv_L12_032': 'පැහැය, වර්ණය, අලංකාරය, ප්‍රශංසාව, පන්තිය (මැස්ක්.)',
    'pv_L12_033': 'සත්‍යය, සත්‍යය (නියුටර්)',
    'pv_L12_034': 'විට (සාපේක්ෂ සර්වනාමය, අවිනිශ්චිත)',
    'pv_L12_035': 'එවිට, එම අවස්ථාවේ දී (ඉවත් කළ නොහැකි)',
    'pv_L12_036': 'නම් (කොන්දේසි සහිත සංයෝජනය)',
    'pv_L12_037': 'දක්වා, (සන්ධිය) තාක්',
    'pv_L12_038': 'පසුව, එම කාලය දක්වා (yāva සහසම්බන්ධය)',
    'pv_L12_039': 'දක්ෂ ලෙස, ප්‍රවේශමෙන් (ක්‍රියා පදය)',
    'pv_L12_040': 'කෝපයෙන් තොරව, කෝපයෙන් නිදහස් (masc.)',
    'pv_L12_041': 'කෝපයට පත් වේ, කෝපයට පත් වේ (උදා: නා කුජ්ජෙය්‍ය = කෝප නොවිය යුතුය)',
    'pv_L12_042': 'ජය ගනී, යටපත් කරයි, ජය ගනී',
    'pv_L12_043': 'ස්වාමියා, නායකයා, සැමියා (masc.)',
    'pv_L12_044': 'ගෞරවනීය සර් (භික්ෂුව / තාපසයා සඳහා ලිපිනය)',
    'pv_L12_045': 'ප්‍රශ්නය (masc.)',
    'pv_L12_046': 'අසයි (pucchituṃ = ඇසීමට)',
    'pv_L12_047': 'සෑම විටම, නිරන්තරයෙන් (ක්‍රියා පදය)',
    'pv_L12_048': 'යවයි, යවයි',
    'pv_L12_049': 'අවබෝධ කරයි, අවබෝධ කරයි, අවබෝධ කරයි',
    'pv_L12_050': 'මිතුරන් (masc./fem.)',
    'pv_L12_051': 'ගෙන එයි, රැගෙන යයි (āhareyyāsi = ඔබ ගෙන ආ යුතුය)',
    'pv_L16_001': 'එක (1) — 3 ස්ත්‍රී පුරුෂ: eko / ekā / ekaṃ',
    'pv_L16_002': 'දෙක (2) — බහු වචන පමණි: dve / duve',
