    'pv_L16_043': 'දොළොස්වන (උදා. 12 වන පරිච්ඡේදය)',
    'pv_L16_044': 'දහසයවන (soḷasamo පරිච්චේදෝ = 16 වන පරිච්ඡේදය)',
    'pv_L16_045': 'පහළොස්වන / 15 වන දිනය (paṇṇarasame divase)',
    'pv_L16_046': 'විසි අටවන — 28 වන දිනය (aṭṭha-vīsatime divase)',
    'pv_L16_047': '29 වැනි ("ek\'ūna-tiṃsatime vasse" = 29 වන වසරේ)',
    'pv_L16_048': '35 වන / 35 වන වසර (pañca-tiṃsatime vasse)',
    'pv_L16_049': 'දින (masc./neuter)',
    'pv_L16_050': 'මෙතැන් සිට, පෙර සිට (නොමැකෙන)',
    'pv_L16_051': 'මාසය (masc./neuter)',
    'pv_L16_052': 'නමුත්, එපමනක් නොව, (ඉවත් කළ නොහැකි)',
    'pv_L16_053': 'පරිච්ඡේදය, කොටස, මායිම, සීමාව (masc.)',
    'pv_L16_054': 'සරණාගතය, රැකවරණය ලබා ගැනීම (නියුටර්)',
    'pv_L16_055': 'ගුණය, සදාචාරය, ශික්ෂා පදය (උදාසීන, සාමාන්‍යයෙන් බහු වචන sīlāni)',
    'pv_L16_056': 'වසර, වැසි සමය (masc./neuter)',
    'pv_L16_057': 'සත්‍යය / සත්‍යය (Ariya-saccāni = චතුරාර්ය සත්‍ය)',
    'pv_L16_058': 'ලෝකය (masc.)',
