    'pv_L16_060': 'අත් (මැස්ක්.)',
    'pv_L16_061': 'ගම්මානය (masc.)',
    'pv_L16_062': 'පොත (උදාසීන)',
    'pv_L16_063': 'පුතා (මැස්ක්.)',
    'pv_L16_064': 'පළතුරු (වපුල්)',
    'pv_L16_065': 'කාන්තාව (fem. -ī)',
    'pv_L16_066': 'අවසන්, අවසාන (විශේෂණ)',
    'pv_L16_067': 'ගෘහපති; බහු ආකාරය gahapatī (masc. -i)',
    'pv_L16_068': 'ගුණවත්, ගුණයෙන් යුක්ත (විශේෂණ)',
    'pv_L16_069': 'උපෝසථ (සමාදන් වීමේ දිනය)',
    'pv_L16_070': 'භික්ෂුව (masc. -u)',
    'pv_L16_071': 'පුහුණු රීතිය, ශික්ෂා පදය (උදාසීන)',
    'pv_L16_072': 'ධනවත් ගෘහපති, කෝටිපති (masc.)',
    'pv_L16_073': 'හතළිස් පහ koṭi / මිලියන 450 (සංයුක්ත සංඛ්‍යා)',
    'pv_L16_074': 'ආයු කාලය, ආයු කාලය (masc./neuter)',
    'pv_L16_075': 'සම්පූර්ණ ස්වයං-බුද්ධිමත් තැනැත්තා (මස්; පූර්ණ බුද්ධත්වයට පත් බුදුන් වහන්සේ)',
    'pv_L16_076': 'ඇස (masc., බහු වචන cakkhūni)',
    'pv_L16_077': 'මුහුණ, මුඛය (වංකය)',
    'pv_L16_078': 'අඹ (masc./neuter)',
    'pv_L16_079': 'ත්‍රි සරණාගතයන් (උදා: බුද්ධ, ධම්ම, Saṅgha)',
    'pv_L16_080': 'ශික්ෂාපද පහ (නපුරු, බහු වචන pañca sīlāni)',
    'pv_L16_081': 'රෝගී පුද්ගලයා (masc./neuter)',
    'pv_L16_082': 'ආයු කාලය (ඉහත බලන්න)',
    'pv_L16_083': 'ධර්මය (masc., බහු වචන Dhammā / Dhammāni ස්ත්‍රී පුරුෂ භාවය අනුව)',
    'pv_L20_001': 'තරුණයා (taruṇa+purisa) — KAMMADHĀRAYA',
    'pv_L20_002': 'තරුණ තරුණිය, තරුණ තරුණිය - KAMMADHĀRAYA (fem.)',
    'pv_L20_003': 'නොඉදුණු පලතුරු, තරුණ පලතුරු - KAMMADHĀRAYA (neut.)',
    'pv_L20_004': 'සඳ මුහුණ (සඳ වැනි මුහුණ) — KAMMADHĀRAYA (masc.)',
    'pv_L20_005': 'ගුණ සම්පත්තිය (ගුණය ධනය ලෙස) — KAMMADHĀRAYA (neut.)',
    'pv_L20_006': 'යහපත් මිනිසා, උතුම් පුද්ගලයා (සු+ජන) — KAMMADHĀRAYA (masc.)',
    'pv_L20_007': 'අහිතකර (අ+කුසල) — KAMMADHĀRAYA (neut.)',
    'pv_L20_008': 'අශ්වයෙක් නොවේ → කොටළුවා (an+assa) — KAMMADHĀRAYA (masc.)',
    'pv_L20_009': 'මිනිසා නොවේ → ආත්මය, අවතාරය (අ+මනුස්ස) — KAMMADHĀRAYA (masc.)',
    'pv_L20_010': 'ප්‍රඥාවන්ත සුමේධා (අනුකූල) — KAMMADHĀRAYA (masc.)',
    'pv_L20_011': 'තුන් ලෝක (එකතුව) - DIGU (neut.)',
    'pv_L20_012': 'චතුරාර්ය සත්‍ය (සත්‍ය හතර, එකතුව) - DIGU (neut.)',
    'pv_L20_013': 'දිශා හතර (එකතු කිරීම) - DIGU (neut.)',
    'pv_L20_014': 'සතියකට (දින හතක්) - DIGU (neut.)',
    'pv_L20_015': 'එකම දරුවා (එක පුතෙක් සිටී) — DIGU / KAMMADHĀRAYA (masc.)',
    'pv_L20_016': 'ගමට ගොස් ඇත (acc.) — TAPPURISA (masc.)',
    'pv_L20_017': 'බුදුන් වහන්සේ විසින් දේශනා කරන ලදී (උපදේශනය) — TAPPURISA (masc.)',
    'pv_L20_018': 'කඩු සටන (උපකරණය - කඩුවෙන්) - TAPPURISA (masc.)',
    'pv_L20_019': 'ලෝකයට ප්‍රයෝජනවත් (dat.) — TAPPURISA (masc.)',
    'pv_L20_020': 'සොරුන්ට ඇති බිය (abl. - සොරුන්ගෙන් ඇති බිය) - TAPPURISA (neut.)',
    'pv_L20_021': 'බුදුන් වහන්සේගේ ධර්මය (උදා.) — තප්පුරිස (මස්)',
    'pv_L20_022': 'වනාන්තරයේ වාසස්ථානය (loc.) — TAPPURISA (masc.)',
    'pv_L20_023': 'ගෝලයා, ශිෂ්‍යයා (ගුරුවරයා අසල ජීවත් වන අයෙක්) — TAPPURISA (masc.)',
    'pv_L20_024': 'රජුට ඇති බිය (උපදේශනය) - TAPPURISA',
    'pv_L20_025': 'මව සහ පියා (mātā+pitaro, සමහර විට Tappurisa හෝ Dvanda බහු වචන ආකාරයෙන්)',
    'pv_L20_026': 'සඳ සහ හිරු — DVANDA (masc. pl.)',
    'pv_L20_027': 'නම-සහ-ආකෘතිය (එකතු කිරීම) — DVANDA (neut.)',
    'pv_L20_028': 'සතුට සහ වේදනාව - DVANDA (neut.)',
    'pv_L20_029': 'අලි, ගවයන් සහ අශ්වයන් (පශු සම්පත් එකතුව) — DVANDA (neut.)',
    'pv_L20_030': 'පුතුන් සහ දියණියන් - DVANDA (masc. pl.)',
    'pv_L20_031': 'කාන්තා සහ පිරිමි — DVANDA (masc. pl.)',
    'pv_L20_032': 'ඇඳන් සහ ආසන (බහුවචන, සාමූහික) — DVANDA (neut. pl.)',
    'pv_L20_033': 'පිරිමි සහ කාන්තා සේවිකාවන් විසින් — DVANDA (fem./masc. pl. instr.)',
    'pv_L20_034': 'භික්ෂු භික්ෂුණීන් - DVANDA',
    'pv_L20_035': 'කහ සිවුර → භික්ෂුව - BAHUBBĪHI (masc.)',
    'pv_L20_036': 'ධර්මය දුටු තැනැත්තා → උත්තමයා — BAHUBBĪHI (masc.)',
    'pv_L20_037': 'තෘෂ්ණාව අත්හැරිය තැනැත්තා → රහතන් වහන්සේ - BAHUBBĪHI (masc.)',
    'pv_L20_038': 'කෙලෙස් අවසන් කළ තැනැත්තා → රහතන් වහන්සේ - BAHUBBĪHI (masc.)',
    'pv_L20_039': 'විශ්වාසවන්ත හදවත් ඇති අය (ඇදහිල්ල ඇති) — BAHUBBĪHI (pl.)',
    'pv_L20_040': 'ක්‍රමයෙන්, පියවරෙන් පියවර — AVYAYĪBHĀVA',
    'pv_L20_041': 'ගඟ අසල, ගඟ අසල - AVYAYĪBHĀVA',
