    'pv_L20_046': 'ආහාරයෙන් පසු, දහවල් - AVYAYĪBHĀVA',
    'pv_L20_047': 'හැකියාව අනුව — AVYAYĪBHĀVA',
    'pv_L20_048': 'ධර්ම දානය (ධර්ම දානය) — TAPPURISA/KAMMADHĀRAYA (neut.)',
    'pv_L20_049': 'ත්‍රි සරණාගතයින් (සරණාගත වීමට ස්ථාන තුනක්) — DIGU/KAMMADHĀRAYA (neut.)',
